package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;

/** The person form's rules, shared by the form and the people import. */
public final class PersonRules {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    private PersonRules() {
    }

    /** The person form's rules for a name, grade, from-date, terms and contact: the request as stored
     *  (name trimmed, blanks as none, contact lower-cased), or refused. */
    public static PersonRequest check(PersonRequest request) throws InvalidSheetException {
        if (request == null || request.name() == null || request.name().trim().isEmpty()) {
            throw new InvalidSheetException("A name is required");
        }
        if (request.grade() == null || !GRADES.contains(request.grade())) {
            throw new InvalidSheetException("The grade must be A, B or C");
        }
        String from = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        try {
            if (!from.isEmpty()) {
                LocalDate.parse(from);
            }
        } catch (DateTimeParseException e) {
            throw new InvalidSheetException("Not a date: " + from);
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty() && !terms.matches("\\d{1,6}")) {
            throw new InvalidSheetException("The terms must be a whole number of days, 0 or more, or blank");
        }
        String contact = request.contact() == null ? "" : request.contact().trim().toLowerCase(java.util.Locale.ROOT);
        // Stored and compared without the spaces around the name; a blank from-date as none.
        return new PersonRequest(request.name().trim(), request.grade(), from.isEmpty() ? null : from,
                request.user(), request.version(),
                terms.isEmpty() ? null : String.valueOf(Integer.parseInt(terms)), contact.isEmpty() ? null : contact);
    }

    /** Refuses a name another person on the sheet, or anyone on another sheet of its tree, has as a name or
     *  alias, or a contact another person on the sheet has. */
    public static void refuseTaken(String sheetId, PersonRequest request, PersonStore store, SettingStore settings)
            throws DuplicateNameException, DuplicateContactException {
        if (store.nameTaken(sheetId.trim(), request.name(), null)
                || store.usedOn(settings.tree(sheetId.trim()), request.name())) {
            throw new DuplicateNameException(request.name());
        }
        if (request.contact() != null && store.contactTaken(sheetId.trim(), request.contact(), null)) {
            throw new DuplicateContactException(request.contact());
        }
    }
}
package net.officefloor.hq.app.person;

/**
 * Body of a person add or edit: the name, the grade (A, B or C), the date (yyyy-MM-dd) an edit
 * records the grade from (blank for the sheet's today; an add's grade applies from the beginning of
 * time) and who makes the change. An edit also carries the version of the person its editor loaded
 * (none for an add). {@code terms} are the person's own terms in whole days, blank (null) for none.
 * {@code contact} is their contact, trimmed and lower-cased, blank (null) for none.
 */
public record PersonRequest(String name, String grade, String gradeFrom, String user, Long version, String terms, String contact) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Val;

/** Applies an edit: the name, and the form's grade recorded from its from-date (the sheet's today when
 *  blank), keeping the grades already recorded — except that a grade left as the row showed it (the one
 *  in force on the sheet's today) with the from-date blank records nothing. Their own terms and contact become the form's
 *  (none when blank). */
public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, SheetStore sheets) {
        person.setName(request.name());
        person.setContact(request.contact());
        person.setTerms(request.terms() == null ? null : Integer.valueOf(request.terms()));
        applyGrade(person, request.grade(), request.gradeFrom(), sheets.today(person.getSheetId()));
    }

    /** Records the grade from the from-date (yyyy-MM-dd, null for the sheet's today), as an edit does: nothing
     *  when the from-date is null and the grade is the one in force on the sheet's today. */
    static void applyGrade(Person person, String grade, String gradeFrom, LocalDate today) {
        if (gradeFrom == null && grade.equals(person.gradeOn(today))) {
            return;
        }
        person.recordGrade(gradeFrom == null ? today : LocalDate.parse(gradeFrom), grade);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

public class SavePerson {
    public void save(@Val Person person, PersonStore store) throws StalePersonException {
        // Stored only over the version loaded, so a save racing this one cannot be overwritten.
        if (!store.save(person)) {
            throw new StalePersonException();
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Val;

/** Records a stored person edit: PERSON_EDITED sheet=<id> by=<user> name=<name> grade=<grade>, the grade
 *  in force on the sheet's today after the save, then terms=<days> when the edit changed their terms (empty when
 *  it cleared them), then contact=<contact> when the edit changed their contact (empty when it cleared it). */
public class AuditPersonEdited {
    public void audit(@Val PersonRequest request, @Val Person person, @Val Rollup before, Audit audit,
            RollupService rollups, SheetStore sheets) {
        audit.record("PERSON_EDITED sheet=" + person.getSheetId() + " by=" + request.user() + " name="
                + person.getName() + " grade=" + person.gradeOn(sheets.today(person.getSheetId()))
                + (person.isTermsChanged() ? " terms=" + (person.getTerms() == null ? "" : person.getTerms()) : "")
                + (person.isContactChanged() ? " contact=" + (person.getContact() == null ? "" : person.getContact()) : ""));
        rollups.record(person.getSheetId(), request.user(), before);
    }
}
package net.officefloor.hq.app.person;

import java.util.Set;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.plugin.variable.Val;

/** Refuses an edit to a name another person on the sheet already has, or a contact another person on the sheet has.
 *  Also refuses one that would leave the person clashing: their new name, or any of their aliases, used as a name or
 *  alias on another sheet of the sheet's tree (see {@link SettingStore#tree}). */
public class CheckNameFreeForEdit {
    public void check(@Val PersonRequest request, @Val Person person, PersonStore store, SettingStore settings)
            throws DuplicateNameException, DuplicateContactException {
        if (store.nameTaken(person.getSheetId(), request.name(), person.getId())) {
            throw new DuplicateNameException(request.name());
        }
        Set<String> tree = store.namesOn(settings.tree(person.getSheetId()));
        if (tree.contains(request.name().trim().toLowerCase(java.util.Locale.ROOT))) {
            throw new DuplicateNameException(request.name());
        }
        for (String alias : person.getAliases()) {
            if (tree.contains(alias.trim().toLowerCase(java.util.Locale.ROOT))) {
                throw new DuplicateNameException(alias);
            }
        }
        if (request.contact() != null && store.contactTaken(person.getSheetId(), request.contact(), person.getId())) {
            throw new DuplicateContactException(request.contact());
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePerson {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PersonRequest request, Out<PersonRequest> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        body.set(PersonRules.check(request));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonStore store, Out<Person> personOut) throws InvalidSheetException {
        Person person = null;
        try {
            person = store.find(sheetId.trim(), Long.parseLong(personId.trim()));
        } catch (NumberFormatException e) {
            // not an id: no such person
        }
        if (person == null) {
            throw new InvalidSheetException("No such person: " + personId);
        }
        personOut.set(person);
    }
}

